// Validate the watchdog payload, then build one Slack message from it.
// Throwing makes n8n answer the webhook with an error, so the watchdog
// falls back to its own Slack webhook instead of losing the alert.
const body = $input.first().json.body;
if (
  !body ||
  body.source !== 'api-contract-watchdog' ||
  body.version !== 1 ||
  !Array.isArray(body.changes)
) {
  throw new Error('Not an api-contract-watchdog version 1 alert payload.');
}

// Slack treats &, < and > as markup.
const escape = (value) =>
  String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const duration = (from, to) => {
  let seconds = Math.max(Math.floor((Date.parse(to) - Date.parse(from)) / 1000), 0);
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  seconds %= 60;
  if (hours) return `${hours}h ${minutes}m`;
  if (minutes) return `${minutes}m ${seconds}s`;
  return `${seconds}s`;
};

const lines = [`*API contract watchdog:* ${escape(body.summary)}`];
for (const change of body.changes) {
  if (change.change === 'failed') {
    lines.push(
      `:red_circle: *FAILED* \`${escape(change.endpoint)}\`: ${escape(change.failed_checks.join(', '))}`
    );
    for (const detail of change.details) {
      lines.push(`    • ${escape(detail)}`);
    }
  } else {
    lines.push(
      `:large_green_circle: *RECOVERED* \`${escape(change.endpoint)}\` after ${duration(change.failing_since, change.at)}`
    );
  }
}
if (body.run_url) {
  lines.push(`<${body.run_url}|View the run>`);
}

return [{ json: { text: lines.join('\n') } }];
